contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, address approved_) public {
        require(amount_ > 0);
        require(loanToCollateral_ > 0);
        require(interest_ > 0);
        require(duration_ > 0);
        require(approved_ != address(0));

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;
        c.clearRequest(0, false, false); if (__ESBMC_reverted()) return;
        c.approveTransfer(approved_, 0); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transferOwnership(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (approved_ != address(this)));
    }
}

