pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, address approved_) internal {
        vm.assume(amount_ > 0);
        vm.assume(loanToCollateral_ > 0);
        vm.assume(interest_ > 0);
        vm.assume(duration_ > 0);
        vm.assume(approved_ != address(0));
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        try c.clearRequest(0, false, false) {} catch { return; }
        try c.approveTransfer(approved_, 0) {} catch { return; }
        bool reverted;
        try c.transferOwnership(0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (approved_ != address(this)));
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, address approved_) public {
        vm.assume(approved_.code.length == 0 && uint160(approved_) > 0xffff && approved_ != address(this) && approved_ != address(c) && approved_ != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && approved_ != 0x000000000000000000636F6e736F6c652e6c6f67 && approved_ != 0x4e59b44847b379578588920cA78FbF26c0B4956C && approved_ != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount_, interest_, loanToCollateral_, duration_, approved_);
    }

    receive() external payable {}
}
